        if stop_id == len(stops) - 1:
            return bus_id
        for next_stop_id in range(stop_id + 1, len(stops)):
            tmp_cost = cost + (stops[next_stop_id] - stops[stop_id])
            if cost > tmp_cost:
                heappush(prior, (tmp_cost, bus_id, next_stop_id, time+1))
                dist_to_end[next_stop_id] = tmp_cost

    return -1

