import sys

def ford_fulkerson(graph, source, sink):
    """
    Performs the Ford-Fulkerson algorithm on a given directed graph.
    Returns the flow and number of augmentations encountered.
    """
    n = len(graph)  # Number of nodes
    residual_graph = {v: [v] * n for v in range(n)}
    queue = [source]
    augmentations = 0

    while queue:
        u = queue.pop(0)
        f = 0
        for v in residual_graph[u]:
            if v != sink and (v != graph[u].keys()[-1] or graph[u][-1] == 0):
                if graph[u][v] == f:
                    continue
                else:
                    if v == source:
                        bypass = [1]
                    elif v == graph[u][-1] + 1 or v == 0 or graph[u][v] == 0:
                        bypass = [0]
                    else:
                        bypass = ford_fulkerson(residual_graph, graph[u][v][-1], v)
                    if bypass != [0] or residual_graph[u][-1] - u == 0:
                        bypass.reverse()
                    f = f + residual_graph[u][-1] - u
                    residual_graph[u].pop(-1)
                    graph[u].pop(v)
                    residual_graph[v].append(u)
                    augmentations += 1
                    break
                if f > 0:
                    queue.append(v)
                    residual_graph[u].append(v)
            if residual_graph[u] == []:
                queue.remove(u)
    return f, augmentations

