from math import gcd
from typing import List

def find_lcm(x: List[int]) -> int:
    """
    Find the least common multiple of a sequence of numbers.
    """
    lcm = x[0]
    for num in x[1:]:
        lcm = lcm * num // gcd(lcm, num)
    return lcm

def find_sequence_len(x_coinicherence: List[int], fcoincidence: List[int]) -> int:
    """ Find length of Firofront cycle starting at x_coinicherence[fcoincidence[len of x_coinicherence]] = 1. """
    cyclenow = 1
    while x_coinicherence[fcoincidence[cyclenow-1]] != 1:
        cyclenow += 1
    return cyclenow

def get_lcm_sequence(X: List[int], Y: List[int]) -> List[int]:
    """ Get lcm sequence of LCMs taken over all pairs (X_i, Y_i) for XX_i in X, XY_i in Y. """
    xlc = sorted(X + [sum(X)])
    ylc = sorted(Y + [sum(Y)])
    lcm_total = find_lcm(xlc) * find_lcm(ylc)
    if lcm_total % find_lcm(xlc) == 0 or lcm_total % find_lcm(ylc) == 0:
        return []
    numer = gcd(lcm_total, sum(Y))
    if (lcm_total < numer < sum(Y) * lcm_common_denominator(Y, X)):
        return []
    return lcm_total // find_lcm(lcm_total)

def lcm_common_denominator(a_list, b_list=None):
    """ Compute the least common multiple of two or more integer sequences, a_list + a_list[0] and b_list + b_list[0] """
    lcm = gcd(a_list[0], b_list[0]) if b_list is not None else a_list[0]
    end = len(a_list)
    if b_list is not None and end > len(b_list):
        end = len(b_list)
    for i in range(1, end):
        lcm = lcm // gcd(a_list[i], lcm) * b_list[i]
    return lcm

def main() -> None:
    test_cases = int(input())

    # Process each test case
    for case in range(test_cases):
        n = int(input())
        a, b = input(), input()

        # Skip test cases where |a| != |b|
