            continue

        a = [ord(digit) for digit in a]
        b = [ord(digit) for digit in b]
        xor_sum = 0
        first_xor = 0
        for _a, _b in zip(a, b):
            xor_sum ^= _a
            first_xor ^= _b

        for _a, _b in zip(a, b):
            a.pop(0)
            b.pop(0)

        if first_xor != 0:
            ans = "-1"
        else:
            lcm_all = 1
            X = []
            for i in range(len(a)):
                if i + 2 <= len(a) and types(a[i]) != types(a[i+len(a)-1])):
                    X = [a[i-2]] + X + [a[i-1]] + a[i:] + [a[i+1]] + [a[i+len(a)-1]] + a[i+len(a):]
                    lcm_all *= 1 + lcm_common_denominator([_a for _a in range(len(a[i-2]) + len(a[i+1]) + 2)])
            if len(X) % 2 != len(a):
                ans = get_lcm_sequence(X, b)

        print(f"{len(ans)} {ans}")

if __name__ == "__main__":
