from typing import List

class ChessBoard:
    def __init__(self, n: int, m: int):
        self.n = n
        self.m = m
        self.available = []
        self.black = set()
        self.white = set()

    def mark_cell(self, row: int, col: int):
        if (row + col) % 2 == 0 and (row, col) not in self.black:
            self.black.add((row, col))
        elif (row + col) % 2 == 1 and (row, col) not in self.white:
            self.white.add((row, col))
        self.available.append((row, col))

    def is_kings_non_attacking(self):
        for row in self.white:
            for col in range(1, 2 * self.n + 1):
                if row + col % 2 == 1 and (row, col) in self.white:
                    break
            else:
                return False
        return True

    def query_result(self):
        total_white = len(self.white)
        total_black = len(self.black)
        return "YES" if total_black == total_white and total_white - total_black > 1 else "NO"


# Read input
