from collections import defaultdict

def is_possible(number_of_glades):
    trails = defaultdict(list)
    for y, x in trails:
        x, y = int(x)-1, int(y)-1
        trails[x].append((y, y+1))
        trails[y].append((x, y))

    visited = set([0])
    my_paths = count_one_path_standard(number_of_glades, trails, len(visited), 0, -1)
    return len(visited) - 1 - my_paths[-1][1]

def is_complete_tree(l):
    if l == 1:
        return True
    return l % 2 == 1 and is_complete_tree(l//2)

def count_one_path_standard(number_of_glades, trails, visited, pos, parent):
    visited.add(pos)
    for dest, cannot_travel in trails[pos]:
        if cannot_travel != parent:
            if is_complete_tree(number_of_glades):
                if dest not in visited:
                    visited.add(dest)
                    after = count_one_path_standard(number_of_glades, trails, visited, dest, pos)
                    visited.remove(dest)
                    return after
                else:
                    return []

    return len(visited)-1
