def min_total_unfamiliar_value(n, k, u):
    dp = defaultdict(lambda: float('inf'))
    dp[0][0] = 0

    for i in range(1, k + 1):
        for j in range(2**i):
            cur = dp[j]
            temp = cur // 2
            if temp == float('inf'):
                continue
            if j == 1:
                dp[j | (2**i)] = temp + u[j][j]
            else:
                dp[j | (2**i)] = min(cur + u[j][j], temp, dp[j << 1 | (2**i)| (2**i)])

