from itertools import accumulate
from heapq import heapify, heappop

def max_spanning_tree(graph, go_weights, trunks_weights):
    n = len(go_weights)
    # Adjust and sort the weights in non-decreasing order
    go_weights_adjusted = list(accumulate(reversed(go_weights)))
    trunks_weights_adjusted = list(accumulate(reversed(trunks_weights)))

    # Calculate the total weight for each possible edge
    edge_weights = []
    for source in range(n):
        for target in range(source, n):
            edge_weights.append((trunks_weights[source] + go_weights[source], source, target))
            edge_weights.append((-go_weights_target, source, target))

    # Sort the edges by their total weight
    edge_weights.sort()

    # Combine the weights from both traversals
    edge_weights += list(accumulate(go_weights))
    edge_weights += list(accumulate(trunks_weights))

    # Find the maximum spanning tree using Prim's algorithm
    graph = {(i, j): go_weights_adjusted[i] + trunks_weights_adjusted[j] for i in range(n) for j in range(i+1)}
    graph = {i: j for i, j in graph.items()}
    pq = [(graph[i, j], i, j) for i in range(n) for j in range(i+1)]
    heapify(pq)

    while pq:
        from_node, from_weight, to_weight = heappop(pq)
        if graph[from_node, to_weight] < from_weight:
            graph[from_node, to_weight] = from_weight
            # Visited can't have the same parent
            visited = (graph[from_node, to_weight], graph[to_weight, from_node])
            while pq and graph[visited] < pq[0][0]:
                heappop(pq)
            if not pq:
                break
            from_weight, to_weight = pq[0]

        # Relax edges within the graph
        for i in range(n):
            if graph[from_node, i] >= from_weight + graph[i, to_weight] and graph[i, to_weight] <= to_weight:
                graph[from_node, i], graph[i, to_weight] = graph[i, to_weight], from_weight
                if pq:
                    heappush(pq, (graph[from_node, i], from_node, i))
            if graph[i, to_weight] >= from_weight + graph[from_node, i] and graph[from_node, i] <= to_weight:
                graph[i, to_weight], graph[from_node, i] = graph[from_node, i], to_weight
                if pq:
                    heappush(pq, (graph[i, to_weight], i, to_weight))

    return sum(graph[i, j] for i, j in graph.keys())

