from collections import defaultdict

def build_graph(go: list, tr: list) -> tuple:
    graph = defaultdict(list)

    min_xor = float('inf')
    for i in range(1, len(go)):
        xor_sum = go[i]
        for j in range(1, len(go)):
            xor_sum += tr[i]*tr[j]
            min_xor = min(min_xor, xor_sum)
            graph[(i, j)].append(xor_sum - tr[i]*tr[j])
            graph[(j, i)].append(xor_sum - tr[i]*tr[j])

    return graph, min_xor

def get_matching(graph: dict, min_xor: int, source: int) -> list:
    matching = [-1]*len(graph)
    edges = []

    for i in range(len(graph)):
        if matching[i] == -1:
            q = [i]
            while q:
                node = q.pop()
                for neighbor in graph[node]:
                    if neighbor < min_xor:
                        matching[i] = source
                        matching[source] = i
                        edges.append((source, i))
                        matching[source], matching[i] = matching[i], matching[source]
                        q = []
                        break
                    if matching[neighbor] == -1:
                        q.append(neighbor)

    return edges

def find_terminals(graph, edges, source: int) -> list:
    terminals = []

    for i, j in edges:
        if i < source and j > source:
            terminals.append(i)
        elif j < source and i > source:
            terminals.append(j)

    return set(terminals)

def max_spanning_tree(weights: list) -> int:
    n = len(weights)
    minimum_spanning_tree = 0

    while n > 1:
        tree, min_xor = build_graph(weights[:n], weights[n-1:])
        edges = [i for i in range(n-1) if tree[i] < min_xor]
        matching = get_matching(tree, min_xor, (n-1,))
        terminals = find_terminals(tree, matching, (n-1,))
        maximum_matching = len(terminals)

        minimum_spanning_tree += sum([weights[x] for x in edges[:(n-1-maximum_matching)]])
        weights.pop(maximum_matching)
        n -= maximum_matching

    return sum(weights)

