        self.root = TrieNode()

    def add(self, s):
        curr = self.root
        for c in s:
            if c not in curr.children:
                curr.children[c] = TrieNode()
            curr = curr.children[c]
        curr.count += 1

    def count_good_partitions(self, l, r):
        return fast_exp3(l, r - 1) * fast_exp3(r - l + 1, -1) % MOD

class Solution:
    def number_of_good_partitions(self, a: int, l: int, r: int) -> int:
        trie = Trie()
        num = a
        while num > 0:
            curr = trie
            for i in range(10):
                if num % 10 == 0:
                    curr.count = 0
                curr.count += curr.children.get(str(i), 0) * fast_exp3(num % 10 - 0, -1)
                num //= 10
            trie.add(str(a % 10 - 0))  # cache 'a'
            trie.add(str(a // 10))
        return trie.root.count

def fast_exp2(a, b, n):
    if b == 0:
        return 1
    half = fast_exp2(a, b // 2, n)
    if b % 2 == 0:
        return (half * half) % n
    else:
        return (a * half * half) % n

def fast_exp3(a, b):
    return fast_exp2(a, b, MOD - 1)

def fast_multiply(base, expn):
    result = 1
    while expn:
        if expn & 1:
            result = fast_multiply(result, base)
        expn >>= 1
        base = base * base % MOD
    return result

