from math import comb

def count_paintings(n, m):
    MOD = 1000000007

    # Base cases
    if n == 1:
        return 1
    if n == 2:
        return 2
    if m == 1:
        return 4
    if m == 2:
        return 12

    # Recursive formula for number of paintings
    # dp(n, m, dx, dy) = dp(m, n, dy, dx) + comb(n, m) - 2*comb(m, dx)
    # where dp(m, n, dx, dy) counts the number of paintings where the top right corner is in (m, n)
    def dp(m, n, dx, dy):
        if (dx, dy) == (0, 0):
            return 1
        if n == 1:
            return comb(m-dy, m)
        if m == 1:
            return comb(n-dx, n)

        res = 0
        for mx in range(m+1):
            for ny in range(n-dy+1):
                if m-dy != ny:
                    res += (comb(mx-dy, mx) + comb(n-mx, n-ny) - 2*comb(m-dy, n-ny)) % MOD
        for nx in range(n+1):
            for my in range(m-dx+1):
                if m-dx != my:
                    res += (comb(nx-dx, nx) + comb(m-nx, m-my) - 2*comb(m-dx, my)) % MOD
        return res % MOD

    total = 0
    for dx in range(-1, 2):
        for dy in range(-1, 2):
            if dx == 0 and dy == 0:
                continue
            total += (dp(m, n, dx, dy) * dp(n, m, dx, dy)) % MOD
    return (total + dp(m, n, 0, 0)) % MOD

