from itertools import product

MOD = 1000000007

def paint_paper(m, n):
    states = set()
    for bit in range(1 << m):
        canvas = [['.' for _ in range(n)] for _ in range(m)]
        for i, j in product(range(m), range(n)):
            if bit & (1 << i):
                canvas[i][j] = '*'
        states.add(str(canvas))
    return states

def count_paintings(m, n):
    states = paint_paper(m, n)
    count = 0
    for state in states:
        # Check if all paining form a connected set
        groups = list(g for _, g in groupby(state, lambda c: c == '*'))
        connected = all(len(groups) == len(g) for g in groups)
        # Check if minimum moves is correct
        if groups[0] and groups[-1] and (len(groups) - 1) % 2 == 0:
            minimum_moves = len(groups) - 1
            for c in groups:
                for i in range(len(c)):
                    if i % 2:
                        minimum_moves -= 1
                    if c[i-1] == '*':
                        minimum_moves -= 1
                    if c[i+1] == '*':
                        minimum_moves -= 1
            if minimum_moves >= 0:
                count += 1
    return count % MOD

