import sys
from bisect import bisect_right

class Bus:
    def __init__(self, si, fi, ti):
        self.start = si
        self.finish = fi
        self.time = ti
        self.bus_id = None

def can_arrive(bus_id, start, finish, buses):
    target_buses = buses.get(str(bus_id))
    if not target_buses:
        return 0

    index = bisect_right(target_buses[1], start)

    if index < len(target_buses[1]):
        if buses[bus_id][0] <= start and finish <= buses[bus_id][1] and buses[bus_id][2] <= buses[bus_id][0]:
            return 1
    return 0

def process_people(input_data, buses):
    m, n = input_data
    person_count = []
    for row in input_data:
        start, finish, time = row
        person = [time, 0]
        if m > 90:
            person[0] += time - start
            person[1] = bisect_right(buses.get(str(time) + "_1"), start)
        person_count.append(person)

    for person in person_count:
        if person[1] >= 109:
            person[1] = -1

    return [person[1] for person in person_count]

