from heapq import heappush, heappop

def find_min_time_queue(num_buses, stops):
    # Create a min-heap with the earliest possible times
    times = [[0, -1]]  # Append the earliest time for the first bus with the same si-fi combination
    for s, f, t in stops:
        while times[0][0] <= t:  # If the earliest time is less than or equal to the current bus's time, pop it
            heappop(times)
        heappush(times, [f, len(stops)])  # Push the last bus time to ensure a new bus starts driving at least at the time of the current decision
        heappush(stops, (f, t))  # Update the last used time of the bus route (to have correct cycle)
    return times

def is_valid_stop_and_bus(stop, buses, times):
    # Check if the bus and time range matches for a stop
    for i, (s, f, t) in enumerate(buses):
        if s <= stop <= f and t <= times[i][-1]:
            return i
    return -1

def find_bus_index(stops, buses, stops_and_buses_map):
