        edge = unprocessed_edges.pop()
        if edge not in processed_edges:
            processed_edges.add(edge)
            neighbors = graph[edge[1]]
            processed_edges.update(neighbors)
            unprocessed_edges.extend(list(neighbor.keys()) for neighbor in neighbors)

