def add_trails_or_is_possible(graph, trails):
    if trails == 0:
        return 0
    unvisited_nodes = list(graph)
    visited_nodes = set()

    while unvisited_nodes:
        curr = unvisited_nodes.pop()
        if curr in visited_nodes:
            continue
        visited_nodes.add(curr)
        if processed_edge + 1 != trails:
            # If Vasya's walk doesn't contain this edge...
            if all(add_trails(graph, n) > 0 for n in graph[curr]):
                return 0
        for r in combinations(unvisited_nodes, trails - len(visited_nodes)):
            if all((n in graph) and (add_trails(graph, n) > 0) for n in set(r) - set(curr)):
                unvisited_nodes.remove(set(r) - set(curr))
        if unvisited_nodes:
            processed_edge += 1

