import sys

def is_balanced(a, b):
    for i in range(len(a)):
        if a[i] != b[(i+len(a)) % len(b)]:
            return False
    return True

def check_reversals(a, b):
    n = len(a)
    if not is_balanced(a, b):
        return 0, []

    def reverse_prefix_prefix(a, prefix_length):
        return a[max(2, (len(a) - prefix_length)):][::-1] + a[:min(prefix_length, len(a))]

    def generate_reversals(a, b, k):
        if k == 0:
            return
        if k == n + 1:
            return
        s = set()
        for i in range(1, n + 1):
            a = reverse_prefix_prefix(a, i)
            if is_balanced(a, b):
                s.add(i)
            else:
                break
        generate_reversals(a, b, k - 1)
        for i in sorted(s):
            generate_reversals(a, b, k - 1)
        return a

    reversing_folds = generate_reversals(a, b, 2)
    return len(reversing_folds) + 1, reversing_folds

