def modinv(x, m):
    """Function to calculate modular inverse of x."""
    y = 1
    z = 0
    while x:
        k = y // x
        y, z = z, y - k * z
        y, z = y % m, z % m
    if y + 2 * m < 0:
        y = y + 2 * m
    return y % m

def generate_partitions(a, l, r):
    MOD = 998244353
    if a <= 0 or l > r or a > 1000000:
        return 0
    base = 987654321
    pos = max(a - r, 0)
    def find_partitions(pos, prev):
        if pos == 0:
            return 1
        ans = 0
        if prev == 0:
            ans = modinv(base ** pos, MOD) * find_partitions(pos - 1, 0) % MOD
        else:
            ans = base ** pos
            if l <= prev * 10 - l <= r:
                ans = modinv(ans, MOD) * find_partitions(pos - 1, prev * 10) % MOD
            if r < prev * 10 + l:
                ans = modinv(ans, MOD) * find_partitions(pos - 1, prev + 1) % MOD
        return ans % MOD
    return find_partitions(a, 0) % MOD

