        nexti, nextj = i + ddxi, j + ddxi * 2
        if nexti > -1 and nexti < n and nextj > -1 and nextj < m and not seen[nexti][nextj]:
            res = dfs(nexti, nextj, n, m, v, seen, stack)
            if res == -1:
                continue
            if res == 1:
                seen[nexti][nextj] = 0
            stack.remove((i, j))
            if not seen[nexti][nextj]:
                seen[nexti][nextj] = 1
                stack.append((nexti, nextj))
                break
    return 0

