from collections import defaultdict

MOD = 1000000007

def is_good_array(arr):
    length = len(arr)
    diff = arr[1] - arr[0] # Initialize difference between first two elements
    for i in range(1, length-1):
        if arr[i+1] - arr[i] != diff:
            return False
    diff += arr[0] - arr[-1] # Check last two elements
    return diff == arr[-1] - arr[0]

def count_grande_arrays(n, m, k, target, memo):
    if k == 0:
        return 1
    if n == 0:
        return 0
    if target < 0:
        return 0

    if (n, target, k) in memo:
        return memo[(n, target, k)]

    ans = 0
    for i in range(target, m+1):
        if is_good_array([i] + [a for a in target_arr if a > i]):
            ans = (ans + count_grande_arrays(n-1, m, k, i, memo)) % MOD

    memo[(n, target, k)] = ans
    return memo[(n, target, k)]

target_arr = list(range(1, m+1))
memo = defaultdict(int)
unique_grande_arrays = count_grande_arrays(len(target_arr), m, k, 0, memo)
